import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{r,o as l,c as i,a as e,e as a,b as d,d as t}from"./app-8893173c.js";const p={},o=e("h1",{id:"定制开发与参与贡献",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#定制开发与参与贡献","aria-hidden":"true"},"#"),a(" 定制开发与参与贡献")],-1),c=e("h2",{id:"webgal-源代码仓库的地址",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#webgal-源代码仓库的地址","aria-hidden":"true"},"#"),a(" WebGAL 源代码仓库的地址")],-1),h={href:"https://github.com/OpenWebGAL/WebGAL",target:"_blank",rel:"noopener noreferrer"},b=t(`<h2 id="分支说明" tabindex="-1"><a class="header-anchor" href="#分支说明" aria-hidden="true">#</a> 分支说明</h2><div class="language-text line-numbers-mode" data-ext="text"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F8F8F2;">main: 稳定版</span></span>
<span class="line"><span style="color:#F8F8F2;">dev: WebGAL 开发版</span></span>
<span class="line"><span style="color:#F8F8F2;">其他分支: 旧版本的留档</span></span>
<span class="line"><span style="color:#F8F8F2;"></span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="更新计划" tabindex="-1"><a class="header-anchor" href="#更新计划" aria-hidden="true">#</a> 更新计划</h2><p>参见 <a href="/info">WebGAL 情报</a></p><h2 id="贡献者指引" tabindex="-1"><a class="header-anchor" href="#贡献者指引" aria-hidden="true">#</a> 贡献者指引</h2><p>如果你想要参与的是 WebGAL Terre 可视化编辑器的贡献，请参考 <a href="terre">WebGAL Terre 贡献者指南</a></p><h3 id="关于-ai-的使用" tabindex="-1"><a class="header-anchor" href="#关于-ai-的使用" aria-hidden="true">#</a> 关于 AI 的使用</h3><p>AI 改变了软件开发的方式，在大幅提高软件开发效率的同时，也带来了诸多挑战。在 UI 编写上，使用 AI 大范围编写 UI 极易出现被称为 “AI Slop” 的问题，AI 编写的 UI 常常不符合人类使用习惯，时而会出现无意义的说明文本，AI 编写的 UI 在布局方面也常常出现溢出、错位等问题。AI 编写代码时也极易为了快速修补错误写出大量冗余代码或“防御性编程”代码。AI 也难以写出更加精简、易于阅读和维护的代码。</p><p>WebGAL 项目，对使用 AI 制定了一些规范，在编写代码时，请遵守这些规范：</p><ol><li><p>人类设计架构和实现方案，AI 编写。我们不接受直接向 AI 说明目标，但人类不参与设计的编码方式。在 AI 编写代码后，需要人工审阅代码，并测试相关模块后，才可以提交 PR。</p></li><li><p>Issue, PR 的文本不允许使用 AI 生成。哪怕不够详细，只需要给出足够的信息定位问题，或说明自己的用意即可。太过于详细的 AI 生成说明反而不容易抓住重点，聚焦于真正重要的信息。</p></li><li><p>对于 UI，应当由人工完成原型设计，AI 只能用于实现。AI 直接根据功能生成的 UI，在我们过去数个版本迭代的经验中，被认为是远远不符合预期的。</p></li></ol><h3 id="参与贡献的要求" tabindex="-1"><a class="header-anchor" href="#参与贡献的要求" aria-hidden="true">#</a> 参与贡献的要求</h3><p>为了帮助我们更好地理解和审核您的贡献，请您注意以下几点：</p><p><strong>提交 Pull Request 前的准备工作</strong>：</p><ol><li><p><em>先提交 Issue</em>： <strong>在开始开发工作前，请先提交一个 Issue 来讨论您的想法和设计方案</strong>。这有助于避免重复工作，确保您的贡献符合项目的方向，并避免 PR 因设计问题无法合并的情况。</p></li><li><p><em>RFC（Request for Comments）</em>： 对于大型改动或新功能，建议先提交 RFC 或详细的设计提案，与维护者和社区成员讨论技术方案的可行性。</p></li></ol><p><strong>代码质量要求</strong>：</p><ol><li><p>为了方便我们理解您的代码思路，建议您在关键部分添加注释说明。</p></li><li><p>如果您添加或修改了功能，请提供相应的测试方法，以确保功能正常运行。如果您进行了代码重构，也请提供测试方法来覆盖受影响的范围，确保重构没有引入新的问题。</p></li><li><p>在提交 Pull Request 时，请简要说明您所做的改动以及背后的原因，并引用相关的 Issue，这将有助于我们更快地理解您的贡献。</p></li></ol><h3 id="在本地启动-webgal-项目" tabindex="-1"><a class="header-anchor" href="#在本地启动-webgal-项目" aria-hidden="true">#</a> 在本地启动 WebGAL 项目</h3><p>WebGAL 目前使用 yarn 作为包管理器，以及 yarn workspace monorepo 管理器。</p><p>如果你没有 yarn ，请输入以下指令安装</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">npm</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">install</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#BD93F9;">-g</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>然后在项目根目录执行</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>以安装依赖。</p><p>本项目有3个 package，分别对应不同的功能：</p><table><thead><tr><th>包名</th><th>内容</th></tr></thead><tbody><tr><td>parser</td><td>WebGAL 解析器</td></tr><tr><td>server</td><td>WebGAL 本地调试服务器</td></tr><tr><td>webgal</td><td>引擎本体</td></tr><tr><td>yukimi</td><td>正在计划中的 yukimi 支持库</td></tr></tbody></table><h2 id="在本地启动-webgal-引擎项目" tabindex="-1"><a class="header-anchor" href="#在本地启动-webgal-引擎项目" aria-hidden="true">#</a> 在本地启动 WebGAL 引擎项目</h2><p>你可以通过运行以下脚本启动开发服务器</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">dev</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果你想要构建 WebGAL，请使用</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#50FA7B;">yarn</span><span style="color:#F8F8F2;"> </span><span style="color:#F1FA8C;">build</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>打包产物在 <code>packages/webgal/dist</code> 目录下。</p><h2 id="关于-webgal-的技术" tabindex="-1"><a class="header-anchor" href="#关于-webgal-的技术" aria-hidden="true">#</a> 关于 WebGAL 的技术</h2><p>WebGAL 是一个已经有一定规模的项目，直接钻进代码中可能会令人感到一时间难以适应。因此，在这里有一份关于 WebGAL 技术的参考文档，帮助你理解 WebGAL 。</p><p><a href="/tech">WebGAL 技术介绍</a></p><p>除此以外，在源代码的一些关键目录，我们也会提供一些说明文档来解释这个模块的原理。这些信息将以中文提供。如今，大语言模型在翻译上的表现已经足够好，所以如果你无法阅读中文，也不必担心。你可以尝试使用大语言模型将其翻译为你的语言。</p><h2 id="将构建后的-webgal-导入-webgal-terre-编辑器" tabindex="-1"><a class="header-anchor" href="#将构建后的-webgal-导入-webgal-terre-编辑器" aria-hidden="true">#</a> 将构建后的 WebGAL 导入 WebGAL Terre 编辑器</h2><div class="hint-container tip"><p class="hint-container-title">提示</p><p>在你完成自定义后，如果你想要使用 WebGAL 编辑器来方便地实时预览和进行资源管理，可以将构建产物作为定制引擎导入 WebGAL Terre，具体请参考 <a href="/derivative">如何使用定制引擎</a>。如果你正在开发 WebGAL Terre 源码，也可以替换 <code>packages/terre2/assets/templates/WebGAL_Template</code> 来更新内置引擎模板。</p></div>`,37);function u(A,m){const s=r("ExternalLinkIcon");return l(),i("div",null,[o,c,e("p",null,[e("a",h,[a("https://github.com/OpenWebGAL/WebGAL"),d(s)])]),b])}const F=n(p,[["render",u],["__file","index.html.vue"]]);export{F as default};
